package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;

final class FieldVisitsAcceptance {
 static String route(String parent,String task){return "/api/openservice/records/incident/"+parent+"/field-visit/"+task;}
 static Map<String,Object> page(WorkflowSupport h,String parent,String task,String user)throws Exception{return FieldDispatchAcceptance.result(h.get(route(parent,task),auth(user)));}
 static Map<String,Object> body(WorkflowSupport h,String parent,String task,String operation)throws Exception{var p=page(h,parent,task,"admin");var work=object(p.get("work"));var result=map("operation",operation,"revision",object(p.get("visit")).get("revision"),"task_revision",object(work.get("task")).get("revision"),"record_revision",Integer.parseInt(object(work.get("parent")).get("sys_mod_count").toString()));switch(operation){case "configure"->result.putAll(map("checklist",List.of("Inspect the installation","Verify the customer result"),"evidence_required",true));case "complete"->result.putAll(map("notes","Customer result verified <script>safe</script>","answers",List.of(1,2),"evidence",List.of(),"parts_reviewed",true));case "incomplete","abort"->result.put("notes","Customer unavailable; follow-up work required");default->{}}return result;}
 static Map<String,Object> send(WorkflowSupport h,String parent,String task,Map<String,Object> body,String user)throws Exception{return FieldDispatchAcceptance.result(h.json("POST",route(parent,task),body,auth(user)));}
 static Map<String,Object> act(WorkflowSupport h,String parent,String task,String operation,String user)throws Exception{return send(h,parent,task,body(h,parent,task,operation),user);}
 static void accepted(WorkflowSupport h,String parent,String task)throws Exception{act(h,parent,task,"configure","admin");FieldDispatchAcceptance.act(h,parent,task,"assign","admin");FieldDispatchAcceptance.act(h,parent,task,"accept","TaskOne");}
 static String upload(WorkflowSupport h,String parent,String name,String content)throws Exception{var r=h.request("POST",h.binaryPath(parent,name),content.getBytes(),"text/plain",auth("TaskOne"));assertEquals(201,r.statusCode(),html(r));return object(parsed(r).get("result")).get("sys_id").toString();}
 static Map<String,Object> part(WorkflowSupport h,String parent,String task,String ci,String direction)throws Exception{var b=body(h,parent,task,"addpart");b.putAll(map("ci_id",ci,"direction",direction,"quantity",2,"notes","Recorded component usage"));return b;}
 static void run(WorkflowSupport h)throws Exception{
  var ids=FieldDispatchAcceptance.setup(h);String parent=ids[0],task=ids[1];assertEquals("unplanned",object(page(h,parent,task,"TaskOne").get("visit")).get("phase"));accepted(h,parent,task);act(h,parent,task,"travel","TaskOne");act(h,parent,task,"checkin","TaskOne");var visit=object(page(h,parent,task,"TaskOne").get("visit"));assertTrue(((Number)visit.get("travelled")).longValue()>0);assertTrue(((Number)visit.get("arrived")).longValue()>=((Number)visit.get("travelled")).longValue());String ci=h.add("cmdb_ci").get("sys_id").toString();var p=send(h,parent,task,part(h,parent,task,ci,"used"),"TaskOne");assertEquals(2,objects(p.get("parts")).getFirst().get("quantity"));assertEquals(400,h.json("POST",route(parent,task),part(h,parent,task,ci,"used"),auth("TaskOne")).statusCode());var remove=body(h,parent,task,"removepart");remove.put("part_id",objects(p.get("parts")).getFirst().get("part_id"));send(h,parent,task,remove,"TaskOne");assertTrue(objects(page(h,parent,task,"TaskOne").get("parts")).isEmpty());send(h,parent,task,part(h,parent,task,ci,"used"),"TaskOne");send(h,parent,task,part(h,parent,task,ci,"removed"),"TaskOne");String file=upload(h,parent,"visit-evidence.txt","Verified terminal result");var complete=body(h,parent,task,"complete");complete.put("evidence",List.of(file));p=send(h,parent,task,complete,"TaskOne");assertEquals("complete",object(p.get("visit")).get("phase"));assertEquals(List.of(1,2),object(p.get("visit")).get("answers"));assertEquals(DigestUtils.sha256Hex("Verified terminal result"),objects(p.get("evidence")).getFirst().get("sha256"));assertEquals(true,objects(p.get("evidence")).getFirst().get("available"));assertEquals("complete",object(object(p.get("work")).get("task")).get("state"));assertEquals("complete",object(object(p.get("work")).get("dispatch")).get("status"));assertEquals(409,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());new Store(h.environment);assertEquals(2,objects(page(h,parent,task,"TaskOne").get("parts")).size());WorkTasksAcceptance.state(h,parent,"2",200);WorkTasksAcceptance.state(h,parent,"6",200);assertEquals(204,h.json("DELETE","/api/now/table/incident/"+parent,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_field_visit"));}
 }
 static void evidence(WorkflowSupport h)throws Exception{
  var ids=FieldDispatchAcceptance.setup(h);String parent=ids[0],task=ids[1];accepted(h,parent,task);act(h,parent,task,"checkin","TaskOne");assertEquals(0L,((Number)object(page(h,parent,task,"TaskOne").get("visit")).get("travelled")).longValue());var complete=body(h,parent,task,"complete");assertEquals(400,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("answers",List.of(1));assertEquals(400,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("answers",List.of(1,1));assertEquals(400,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("answers",List.of(1,2));complete.put("parts_reviewed",false);assertEquals(400,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("parts_reviewed",true);
  String foreign=h.add("incident").get("sys_id").toString(),other=upload(h,foreign,"other.txt","Other case evidence"),file=upload(h,parent,"receipt.txt","original evidence");complete.put("evidence",List.of(other));assertEquals(404,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("evidence",List.of(file,file));assertEquals(400,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());complete.put("evidence",List.of(file));String api="/api/openservice/attachment-access/"+file;var held=AttachmentHoldsAcceptance.result(h,api);FieldDispatchAcceptance.result(h.json("POST",api,map("held",true,"review",held.get("review"),"reason","Review evidence"),auth("admin")));assertEquals(423,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());held=AttachmentHoldsAcceptance.result(h,api);FieldDispatchAcceptance.result(h.json("POST",api,map("held",false,"review",held.get("review"),"reason","File checked"),auth("admin")));
  try(var db=h.store.open()){db.update("INSERT INTO os_attachment_scan(attachment_id,revision,status,sha256,engine,completed_at,hold_revision,release_on_clean) VALUES(?,1,'pending','','test',0,0,0)",file);db.connection.commit();}assertEquals(423,h.json("POST",route(parent,task),complete,auth("TaskOne")).statusCode());assertEquals("onsite",object(page(h,parent,task,"TaskOne").get("visit")).get("phase"));try(var db=h.store.open()){db.update("UPDATE os_attachment_scan SET status='clean',sha256=? WHERE attachment_id=?",DigestUtils.sha256Hex("original evidence"),file);db.connection.commit();}var p=send(h,parent,task,complete,"TaskOne");assertEquals(true,objects(p.get("evidence")).getFirst().get("available"));held=AttachmentHoldsAcceptance.result(h,api);FieldDispatchAcceptance.result(h.json("POST",api,map("held",true,"review",held.get("review"),"reason","Later review"),auth("admin")));assertEquals(false,objects(page(h,parent,task,"TaskOne").get("evidence")).getFirst().get("available"));try(var db=h.store.open()){db.update("UPDATE os_attachment SET quarantined=0,content=? WHERE sys_id=?","changed evidence".getBytes(),file);db.connection.commit();}assertEquals(false,objects(page(h,parent,task,"TaskOne").get("evidence")).getFirst().get("available"));assertEquals(204,h.json("DELETE","/api/now/attachment/"+file,map(),auth("admin")).statusCode());assertEquals(false,objects(page(h,parent,task,"TaskOne").get("evidence")).getFirst().get("available"));
  String second=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),true);accepted(h,parent,second);var config=body(h,parent,second,"configure");config.put("evidence_required",false);send(h,parent,second,config,"TaskTwo");act(h,parent,second,"checkin","TaskOne");assertEquals("complete",object(act(h,parent,second,"complete","TaskOne").get("visit")).get("phase"));
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=FieldDispatchAcceptance.setup(h);String parent=ids[0],task=ids[1];for(String user:List.of("TaskOther","TaskReader"))assertEquals(403,h.get(route(parent,task),auth(user)).statusCode());act(h,parent,task,"configure","admin");assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"travel"),auth("TaskOne")).statusCode());FieldDispatchAcceptance.act(h,parent,task,"assign","admin");FieldDispatchAcceptance.act(h,parent,task,"accept","TaskOne");for(String user:List.of("admin","TaskTwo"))assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"travel"),auth(user)).statusCode());assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"abort"),auth("TaskTwo")).statusCode());
  Map<String,Object> original,ciSchema;try(var db=h.store.open()){original=Service.schema(db,"incident");ciSchema=Service.schema(db,"cmdb_ci");}var schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,h.json("POST",route(parent,task),body(h,parent,task,"travel"),auth("TaskOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}for(String field:List.of("description","state")){schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,h.get(route(parent,task),auth("TaskOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  RecordScopesAcceptance.member(h,ids[2],FieldDispatchAcceptance.uid(h,"TaskOne"),false);assertEquals(403,h.get(route(parent,task),auth("TaskOne")).statusCode());RecordScopesAcceptance.member(h,ids[2],FieldDispatchAcceptance.uid(h,"TaskOne"),true);ProblemInvestigationsAcceptance.access(h,"incident",parent,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.get(route(parent,task),auth("TaskOne")).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",parent,"workspace","");act(h,parent,task,"travel","TaskOne");assertEquals(409,h.json("POST",FieldDispatchAcceptance.route(parent,task),FieldDispatchAcceptance.body(h,parent,task,"release"),auth("admin")).statusCode());act(h,parent,task,"checkin","TaskOne");
  for(String operation:List.of("complete","cancel")){var bypass=WorkTasksAcceptance.command(h,parent,operation,task);bypass.put(operation.equals("complete")?"outcome":"reason","Bypass visit report");assertEquals(409,h.json("POST",WorkTasksAcceptance.api(parent),bypass,auth("admin")).statusCode());}
  String ci=h.add("cmdb_ci").get("sys_id").toString();send(h,parent,task,part(h,parent,task,ci,"used"),"TaskOne");ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"private",FieldDispatchAcceptance.uid(h,"admin"));var hidden=objects(page(h,parent,task,"TaskOne").get("parts")).getFirst();assertEquals(false,hidden.get("accessible"));assertFalse(hidden.containsKey("ci_id"));assertEquals("",hidden.get("notes"));ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ci,"workspace","");schema=new LinkedHashMap<>(ciSchema);schema.put("field_rules",map("short_description",map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",schema);try{var p=page(h,parent,task,"TaskOne");assertEquals("Configuration item",objects(p.get("parts")).getFirst().get("label"));assertTrue(objects(object(p.get("search")).get("items")).isEmpty());}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",ciSchema);}
  try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='TaskOne'");db.connection.commit();}var aborted=act(h,parent,task,"abort","admin");assertEquals("incomplete",object(aborted.get("visit")).get("phase"));assertEquals("cancelled",object(object(aborted.get("work")).get("task")).get("state"));assertEquals("cancelled",object(object(aborted.get("work")).get("dispatch")).get("status"));WorkTasksAcceptance.state(h,parent,"2",200);WorkTasksAcceptance.state(h,parent,"6",409);WorkTasksAcceptance.act(h,parent,task,"waive","admin","Create replacement work for the incomplete visit");WorkTasksAcceptance.state(h,parent,"6",200);
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=FieldDispatchAcceptance.setup(h);String parent=ids[0],task=ids[1],api=route(parent,task),ui="/record/incident/"+parent+"/field-visit/"+task;assertEquals(405,h.json("PUT",api,map(),auth("admin")).statusCode());assertEquals(400,h.get(api+"?unknown=1",auth("admin")).statusCode());assertEquals(400,h.get(api+"?limit=0",auth("admin")).statusCode());assertEquals(400,h.json("POST",api+"?q=test",body(h,parent,task,"configure"),auth("admin")).statusCode());assertEquals(404,h.get(route(parent,Values.id()),auth("admin")).statusCode());assertEquals(400,h.json("POST",api,map("operation","unknown"),auth("admin")).statusCode());
  for(var changes:List.of(map("extra",1),map("revision",-1),map("checklist","one"),map("checklist",List.of()),map("checklist",Collections.nCopies(21,"Check")),map("checklist",List.of("Same","Same")),map("checklist",List.of(" ")),map("checklist",List.of("x".repeat(161))),map("evidence_required","true"))){var bad=body(h,parent,task,"configure");bad.putAll(changes);assertEquals(400,h.json("POST",api,bad,auth("admin")).statusCode());}for(String field:List.of("revision","task_revision","record_revision")){var bad=body(h,parent,task,"configure");bad.put(field,999);assertEquals(409,h.json("POST",api,bad,auth("admin")).statusCode());}
  FieldDispatchAcceptance.act(h,parent,task,"assign","admin");FieldDispatchAcceptance.act(h,parent,task,"accept","TaskOne");assertEquals(400,h.json("POST",api,body(h,parent,task,"travel"),auth("TaskOne")).statusCode());act(h,parent,task,"configure","TaskTwo");var old=body(h,parent,task,"travel");act(h,parent,task,"travel","TaskOne");assertEquals(409,h.json("POST",api,old,auth("TaskOne")).statusCode());assertEquals(400,h.json("POST",api,body(h,parent,task,"travel"),auth("TaskOne")).statusCode());assertEquals(400,h.json("POST",api,body(h,parent,task,"configure"),auth("admin")).statusCode());assertEquals(400,h.json("POST",api,body(h,parent,task,"complete"),auth("TaskOne")).statusCode());String ci=h.add("cmdb_ci").get("sys_id").toString();assertEquals(400,h.json("POST",api,part(h,parent,task,ci,"used"),auth("TaskOne")).statusCode());var removal=body(h,parent,task,"removepart");removal.put("part_id",Values.id());assertEquals(400,h.json("POST",api,removal,auth("TaskOne")).statusCode());act(h,parent,task,"checkin","TaskOne");assertEquals(400,h.json("POST",api,body(h,parent,task,"checkin"),auth("TaskOne")).statusCode());
  for(Object count:List.of(0,-1,10001,1.5,"1")){var bad=part(h,parent,task,ci,"used");bad.put("quantity",count);assertEquals(400,h.json("POST",api,bad,auth("TaskOne")).statusCode());}for(var change:List.of(map("direction","other"),map("notes"," "),map("notes","x".repeat(1001)))){var bad=part(h,parent,task,ci,"used");bad.putAll(change);assertEquals(400,h.json("POST",api,bad,auth("TaskOne")).statusCode());}assertEquals(404,h.json("POST",api,part(h,parent,task,Values.id(),"used"),auth("TaskOne")).statusCode());removal=body(h,parent,task,"removepart");removal.put("part_id",Values.id());assertEquals(404,h.json("POST",api,removal,auth("TaskOne")).statusCode());
  for(var change:List.of(map("notes",""),map("notes","x".repeat(4001)),map("answers","one"),map("answers",List.of("1",2)),map("answers",List.of(0,2)),map("answers",List.of(1,3)),map("evidence","file"),map("evidence",Collections.nCopies(11,Values.id())),map("evidence",List.of("x".repeat(32))))){var bad=body(h,parent,task,"complete");bad.putAll(change);assertEquals(400,h.json("POST",api,bad,auth("TaskOne")).statusCode());}
  assertEquals(400,h.protectedForm(ui,map("revision","bad"),auth("admin")).statusCode());var form=new LinkedHashMap<>(body(h,parent,task,"configure"));form.put("checklist","Inspect\nVerify");form.put("evidence_required","maybe");assertEquals(400,h.protectedForm(ui,form,auth("admin")).statusCode());form=new LinkedHashMap<>(part(h,parent,task,ci,"used"));form.put("quantity","bad");assertEquals(400,h.protectedForm(ui,form,auth("TaskOne")).statusCode());form=new LinkedHashMap<>(body(h,parent,task,"complete"));form.remove("answers");form.remove("evidence");form.put("parts_reviewed","true");form.put("answer_1","false");assertEquals(400,h.protectedForm(ui,form,auth("TaskOne")).statusCode());form.remove("answer_1");form.put("evidence_"+Values.id(),"false");assertEquals(400,h.protectedForm(ui,form,auth("TaskOne")).statusCode());
  try(var db=h.store.open()){db.update("UPDATE os_case_task SET assignee_id=? WHERE task_id=?",RecordAccess.owner(db,"TaskTwo"),task);db.connection.commit();}assertEquals(403,h.json("POST",api,body(h,parent,task,"incomplete"),auth("TaskOne")).statusCode());act(h,parent,task,"abort","admin");assertEquals(409,h.json("POST",api,body(h,parent,task,"configure"),auth("admin")).statusCode());
 }
 static void limits(WorkflowSupport h)throws Exception{
  var ids=FieldDispatchAcceptance.setup(h);String parent=ids[0],task=ids[1];accepted(h,parent,task);var config=body(h,parent,task,"configure");var checks=new ArrayList<String>();for(int n=1;n<=20;n++)checks.add("Required check "+n);config.put("checklist",checks);config.put("evidence_required",false);send(h,parent,task,config,"admin");act(h,parent,task,"checkin","TaskOne");String ci="";for(int n=0;n<20;n++){ci=h.add("cmdb_ci").get("sys_id").toString();var usage=part(h,parent,task,ci,"used");usage.put("quantity",n==0?1:10000);send(h,parent,task,usage,"TaskOne");}assertEquals(20,objects(page(h,parent,task,"TaskOne").get("parts")).size());assertEquals(400,h.json("POST",route(parent,task),part(h,parent,task,ci,"removed"),auth("TaskOne")).statusCode());var completed=body(h,parent,task,"complete");completed.put("answers",java.util.stream.IntStream.rangeClosed(1,20).boxed().toList());send(h,parent,task,completed,"TaskOne");
  for(String phase:List.of("planned","travelling","onsite")){String next=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);accepted(h,parent,next);if(phase.equals("travelling"))act(h,parent,next,"travel","TaskOne");if(phase.equals("onsite"))act(h,parent,next,"checkin","TaskOne");assertEquals("incomplete",object(act(h,parent,next,"incomplete","TaskOne").get("visit")).get("phase"));}
  String queued=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);act(h,parent,queued,"configure","admin");var cancel=WorkTasksAcceptance.command(h,parent,"cancel",queued);cancel.put("reason","Skip visit report");assertEquals(409,h.json("POST",WorkTasksAcceptance.api(parent),cancel,auth("admin")).statusCode());act(h,parent,queued,"abort","admin");String assigned=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);act(h,parent,assigned,"configure","admin");FieldDispatchAcceptance.act(h,parent,assigned,"assign","admin");assertEquals("cancelled",object(object(act(h,parent,assigned,"abort","admin").get("work")).get("dispatch")).get("status"));
  String ordinary=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);WorkTasksAcceptance.act(h,parent,ordinary,"cancel","TaskOne","Ordinary task remains independently cancellable");String closed=WorkTasksAcceptance.create(h,parent,ids[2],List.of(),false);act(h,parent,closed,"configure","admin");WorkTasksAcceptance.state(h,parent,"2",200);WorkTasksAcceptance.state(h,parent,"6",200);assertEquals(409,h.json("POST",route(parent,closed),body(h,parent,closed,"configure"),auth("admin")).statusCode());assertEquals("planned",object(page(h,parent,closed,"admin").get("visit")).get("phase"));assertFalse(html(h.get("/record/incident/"+parent+"/field-visit/"+closed,auth("admin"))).contains("End stranded visit as incomplete"));
 }

}
